package com.shopsmart.service;
import com.shopsmart.cart.*;import com.shopsmart.product.*;import com.shopsmart.user.UserRepository;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.util.List;
@Service public class CartService {private final CartRepository carts;private final ProductRepository products;private final UserRepository users;public CartService(CartRepository c,ProductRepository p,UserRepository u){carts=c;products=p;users=u;}public List<CartItem> get(String e){return carts.findByUserEmailOrderByAddedAtAsc(e);}@Transactional public List<CartItem> add(String e,Long id,int q){var u=users.findByEmail(e).orElseThrow();var p=products.findById(id).filter(Product::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));var i=carts.findByUserEmailAndProductId(e,id).orElseGet(()->new CartItem(u,p,0));if(i.getQuantity()+q>p.getStock())throw new ResponseStatusException(HttpStatus.CONFLICT,"Requested quantity exceeds available stock");i.setQuantity(i.getQuantity()+q);carts.save(i);return get(e);}@Transactional public List<CartItem> updateQuantity(String e,Long productId,int q){var i=carts.findByUserEmailAndProductId(e,productId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Cart item not found"));var p=products.findById(productId).filter(Product::isActive).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Product not found"));if(q>p.getStock())throw new ResponseStatusException(HttpStatus.CONFLICT,"Requested quantity exceeds available stock");i.setQuantity(q);carts.save(i);return get(e);}@Transactional public List<CartItem> remove(String e,Long id){carts.findByUserEmailAndProductId(e,id).ifPresent(carts::delete);return get(e);}@Transactional public void clear(String e){carts.deleteByUserEmail(e);}}
